在 scripts/run-daily-tasks.mjs 的失败分支中，增加对 pulse 任务板的同步回写：

```js
// 在 failures.push 之前，对 assignment 对应的 pulse 任务调用 taskCommand
if (assignment?.id) {
  try {
    const pulseState = pulseAssignments?.task_board || [];
    const cmd = {
      task_id: assignment.id,
      agent: ch.agent,
      action: 'release_task',
      reason: res.status
    };
    // 如果任务是 claimed 状态，释放回 assigned 便于次日重试
    const claimed = pulseState.find(t => t.id === assignment.id && t.claimed_by === ch.agent);
    if (claimed) {
      claimed.status = 'assigned';
      claimed.claimed_by = null;
      claimed.claim_actor = null;
      claimed.claimed_at = null;
      claimed.claim_kind = null;
      claimed.released_at = new Date().toISOString();
      claimed.release_reason = res.status;
      claimed.recovery_attempts = (claimed.recovery_attempts || 0) + 1;
    }
    fs.writeFileSync(
      path.join(ROOT, 'knowledge/results/pulse/task-board.json'),
      JSON.stringify({...pulseAssignments, task_board: pulseState, updated_at: new Date().toISOString()}, null, 2)
    );
  } catch (e) {
    console.warn(`[run-daily-tasks] pulse board update failed for ${ch.agent}:`, e);
  }
}
```

同时保持 pending-reminders 原有逻辑不变，确保下次运行可通过 dailyAssignment 查找到已回退为 assigned 状态的任务。
